package pzvrphysicality;

import java.lang.ref.WeakReference;import java.util.*;import local.pzvr.Engine;import zombie.characters.IsoPlayer;import zombie.inventory.InventoryItem;import zombie.iso.objects.IsoWorldInventoryObject;

/** Short native-drop transition. Detached pose waits for actual visible ground admission before mesh physics. */
public final class MoveableDropBootstrap {
 public record Ready(InventoryItem item,IsoWorldInventoryObject source,MoveableGeometry.Geometry geometry,float[] pose,float[] velocity){public Ready{pose=pose.clone();velocity=velocity.clone();}public float[] pose(){return pose.clone();}public float[] velocity(){return velocity.clone();}}
 private record Pending(WeakReference<IsoPlayer> actor,WeakReference<Object> cell,WeakReference<IsoWorldInventoryObject> source,WeakReference<zombie.iso.IsoGridSquare> square,WeakReference<viewpoint.packs.PackBind> provider,MoveableCarry.Drop drop,float[] velocity,long itemEpoch,long modeEpoch,long rigGeneration,long time,float x,float y,float z){Pending{velocity=velocity.clone();}}
 private static final WeakHashMap<InventoryItem,Pending> pending=new WeakHashMap<>();
 public static synchronized void clear(){pending.clear();}
 public static synchronized boolean stage(IsoPlayer actor,InventoryItem item,IsoWorldInventoryObject source,MoveableCarry.Drop drop,float[] velocity,long itemEpoch){
  if(actor==null||item==null||source==null||drop==null||velocity==null||velocity.length!=3||pending.size()>=24&&!pending.containsKey(item))return false;for(float value:velocity)if(!Float.isFinite(value)||Math.abs(value)>20)return false;
  var rig=WorldRigCapture.latest;if(rig==null||rig.actor()!=actor)return false;var value=new Pending(new WeakReference<>(actor),new WeakReference<>(actor.getCell()),new WeakReference<>(source),new WeakReference<>(source.getSquare()),new WeakReference<>(item instanceof zombie.inventory.types.Moveable movable?viewpoint.packs.ModelPacks.bind(movable.getWorldSprite()):null),drop,velocity,itemEpoch,MoveableModels.epoch(),rig.generation(),System.nanoTime(),source.getWorldPosX(),source.getWorldPosY(),source.getWorldPosZ());if(!valid(item,value,System.nanoTime()))return false;pending.put(item,value);MoveableModels.requestRedraw();return true;
 }
 private static boolean valid(InventoryItem item,Pending value,long now){var actor=value.actor.get();var source=value.source.get();var input=Engine.latestInput;var rig=WorldRigCapture.latest;var geometry=MoveableRenderHook.geometry(item);return Float.isFinite(item.getActualWeight())&&item.getActualWeight()>0&&item.getActualWeight()<=20&&MoveableModels.enabled()&&Main.ready()&&actor!=null&&IsoPlayer.players.length>0&&IsoPlayer.players[0]==actor&&!actor.isDead()&&actor.getVehicle()==null&&actor.getCell()==value.cell.get()&&!zombie.network.GameClient.client&&!zombie.network.GameServer.server&&!zombie.GameTime.isGamePaused()&&Engine.active()&&Engine.worldPresent&&input!=null&&input.focused()&&rig!=null&&rig.actor()==actor&&rig.generation()==value.rigGeneration&&rig.fresh(now)&&input.time()==rig.inputTime()&&value.itemEpoch==NativeItems.epoch()&&value.modeEpoch==MoveableModels.epoch()&&now>=value.time&&now-value.time<=2_000_000_000L&&source!=null&&item.getWorldItem()==source&&source.getItem()==item&&item.getContainer()==null&&source.getSquare()!=null&&source.getSquare()==value.square.get()&&actor.getCell().getGridSquare(source.getSquare().getX(),source.getSquare().getY(),source.getSquare().getZ())==source.getSquare()&&item instanceof zombie.inventory.types.Moveable movable&&viewpoint.packs.ModelPacks.bind(movable.getWorldSprite())==value.provider.get()&&value.provider.get()!=null&&source.getSquare().getWorldObjects().contains(source)&&source.getWorldPosX()==value.x&&source.getWorldPosY()==value.y&&source.getWorldPosZ()==value.z&&geometry!=null&&geometry.source()==value.drop.geometry().source()&&geometry.yaw()==value.drop.geometry().yaw()&&geometry.scale()==value.drop.geometry().scale();}
 public static synchronized float[] pose(InventoryItem item,IsoWorldInventoryObject source){var value=pending.get(item);if(value==null)return null;if(value.source.get()!=source||!valid(item,value,System.nanoTime())){pending.remove(item);return null;}return value.drop.pose();}
 public static synchronized List<Ready> ready(IsoPlayer actor,long now){var result=new ArrayList<Ready>();for(var iterator=pending.entrySet().iterator();iterator.hasNext();){var entry=iterator.next();var item=entry.getKey();var value=entry.getValue();if(value.actor.get()!=actor||!valid(item,value,now)){iterator.remove();continue;}var source=value.source.get();if(MoveableRenderHook.readyGround(item,source)){result.add(new Ready(item,source,value.drop.geometry(),value.drop.pose(),value.velocity));}}return List.copyOf(result);}
 public static synchronized boolean complete(Ready receipt){if(receipt==null)return false;var value=pending.get(receipt.item());if(value==null||value.source.get()!=receipt.source()||value.drop.geometry()!=receipt.geometry()||!Arrays.equals(value.drop.pose(),receipt.pose())||!Arrays.equals(value.velocity,receipt.velocity())||!valid(receipt.item(),value,System.nanoTime()))return false;pending.remove(receipt.item());return true;}
 public static synchronized int count(){return pending.size();}
 private MoveableDropBootstrap(){}
}
